parameters.functionCode:
const response = $input.first().json.choices[0].message.content;

try {
  const content = JSON.parse(response);
  return {
    ...content,
    chatId: $input.first().json.chatId
  };
} catch (e) {
  // Fallback parsing
  const lines = response.split('\n');
  const hashtags = lines.filter(l => l.includes('#')).map(l => l.trim());
  const postContent = lines.filter(l => !l.includes('#')).join('\n');

  return {
    postContent: postContent || response,
    hashtags: hashtags.length > 0 ? hashtags : ['#LinkedIn', '#ProfessionalDevelopment'],
    engagementTips: ['Ask questions', 'Use emojis', 'Tag relevant people'],
    wordCount: (postContent || response).split(' ').length,
    chatId: $input.first().json.chatId,
    rawResponse: response
  };
}
